public static void cycleToNextSigil(ItemStack itemStack, int mode)
	{
		if (itemStack.getItem() instanceof ItemSigilHolding)
		{
			initModeTag(itemStack);

			int index = mode;
			if (mode == 120 || mode == -120)
			{
				int currentIndex = getCurrentItemOrdinal(itemStack);
				ItemStack currentItemStack = getItemStackInSlot(itemStack, currentIndex);
				if (currentItemStack.isEmpty())
					return;
				if (mode < 0)
				{
					index = next(currentIndex);
					currentItemStack = getItemStackInSlot(itemStack, index);

					while (currentItemStack.isEmpty())
					{
						index = next(index);
						currentItemStack = getItemStackInSlot(itemStack, index);
					}
				} else
				{
					index = prev(currentIndex);
					currentItemStack = getItemStackInSlot(itemStack, index);

					while (currentItemStack.isEmpty())
					{
						index = prev(index);
						currentItemStack = getItemStackInSlot(itemStack, index);
					}
				}
			}

			itemStack.getTag().putInt(Constants.NBT.CURRENT_SIGIL, index);
		}
	}

public static ItemStack getItemStackInSlot(ItemStack itemStack, int slot)
	{
		if (itemStack.getItem() instanceof ItemSigilHolding)
		{
			List<ItemStack> inv = getInternalInventory(itemStack);
			if (inv != null)
				return inv.get(slot == 5 ? 4 : slot);
			else
				return ItemStack.EMPTY;
		}

		return ItemStack.EMPTY;
	}

public static int next(int mode)
	{
		int index = mode + 1;

		if (index >= inventorySize)
		{
			index = 0;
		}

		return index;
	}

public static int prev(int mode)
	{
		int index = mode - 1;

		if (index < 0)
		{
			index = inventorySize;
		}

		return index;
	}

@SubscribeEvent
	public static void loadModels(final ModelEvent.RegisterGeometryLoaders event) {
		event.register("mimicloader", new MimicModelLoader(BloodMagic.rl("block/solidopaquemimic")));
		event.register("mimicloader_ethereal", new MimicModelLoader(BloodMagic.rl("block/etherealopaquemimic")));

		event.register("loader_holding", new SigilHoldingModelLoader(BloodMagic.rl("item/sigilofholding_base")));
	}

public static void cycleSigil(ItemStack stack, Player player, int dWheel)
	{
		int mode = dWheel;
		if (!ConfigManager.CLIENT.sigilHoldingSkipsEmptySlots.get())
		{
			mode = ItemSigilHolding.getCurrentItemOrdinal(stack);
			mode = dWheel < 0 ? ItemSigilHolding.next(mode) : ItemSigilHolding.prev(mode);
		}

		ItemSigilHolding.cycleToNextSigil(stack, mode);
		BloodMagicPacketHandler.INSTANCE.sendToServer(new SigilHoldingPacket(player.getInventory().selected, mode));
		ItemStack newStack = ItemSigilHolding.getItemStackInSlot(stack, ItemSigilHolding.getCurrentItemOrdinal(stack));
		player.displayClientMessage(newStack.isEmpty() ? Component.literal("") : newStack.getDisplayName(), true);
	}

@SubscribeEvent
	public void onMouseEvent(InputEvent.MouseScrollingEvent event)
	{
		LocalPlayer player = Minecraft.getInstance().player;

		if (event.getScrollDelta() != 0 && player != null && player.isShiftKeyDown())
		{
			ItemStack stack = player.getMainHandItem();

			if (!stack.isEmpty())
			{
				Item item = stack.getItem();

				if (item instanceof ItemSigilHolding)
				{
					cycleSigil(stack, player, event.getScrollDelta() > 0 ? 1 : -1);
					event.setCanceled(true);
				}
			}
		}
	}

public static void handle(SigilHoldingPacket message, Supplier<Context> context)
	{
		context.get().enqueueWork(() -> sendKeyToServer(message, context.get().getSender()));
		context.get().setPacketHandled(true);
	}

public static void sendKeyToServer(SigilHoldingPacket msg, Player playerEntity)
	{
		ItemStack itemStack = ItemStack.EMPTY;

		if (msg.slot > -1 && msg.slot < 9)
		{
			itemStack = playerEntity.getInventory().getItem(msg.slot);
		}

		if (!itemStack.isEmpty())
		{
			ItemSigilHolding.cycleToNextSigil(itemStack, msg.mode);
		}
	}

